"use strict";(self.webpackChunk_N_E=self.webpackChunk_N_E||[]).push([[58868],{58868:function(n){n.exports=JSON.parse('{"content":"\\n<center>\\n<BookCard \\n          cover=\\"/assets/snippets/books/the-red-finger.png\\"\\n          title=\\"붉은 손가락\\"\\n          author=\\"히가시노 게이고\\"\\n          publisher=\\"현대문학\\"\\n          publishedDate=\\"2007-07-25\\"\\n          isbn=\\"9788972753940\\"\\n          rating=3.5\\n          tags=\\"mystery\\"\\n        />\\n</center>\\n\\n## Review\\n살인 사건이라는 극적인 장치를 통해 평범해 보이는 한 가족의 도덕적, 정서적 붕괴를 보여준다.  \\n이 작품에서의 미스터리는 ```누가 범인인가```가 아니라 <mark>어떻게 이 비극이 가능했는가</mark>인 듯하다.  \\n<br>\\n이 작품에서는 사건의 범인이 초반에 공개되어, 작가가 의도적으로 작품의 핵심 질문이 ```누가```가 아니라는 것을 밝힌다.  \\n<br>\\n가족이라는 이름 아래 자신들이 만들어낸 괴물을 보호하기 위해 가장 연약한 구성원을 희생시키는 냉정한 상황을 그린다.  \\n<br>\\n작가는 작품을 통해 대가족의 붕괴, 노인 소외 문제, 부모의 지도 부재에 대한 날카로운 비판을 하는 듯하다."}')}}]);